python3 - <<'EOF'
import re
p='lib/format.ts'
s=open(p).read()
start=s.index("const EMPTY_CARD")
s=s[:start]+'''export interface GridRow {
  kind: 'row' | 'loader';
  [key: string]: unknown;
}

/** Groups cards into 2-column rows with flat l*/r* fields (flat paths bind reliably in ListView cells). */
export function toRows(cards: CardVM[]): GridRow[] {
  const rows: GridRow[] = [];
  for (let i = 0; i < cards.length; i += 2) {
    const row: GridRow = { kind: 'row' };
    const pairs: [string, CardVM | undefined][] = [
      ['l', cards[i]],
      ['r', cards[i + 1]],
    ];
    for (const [side, c] of pairs) {
      row[`${side}Handle`] = c?.handle ?? '';
      row[`${side}TestID`] = c?.testID ?? '';
      row[`${side}Image`] = c?.image ?? '';
      row[`${side}ImageHeight`] = GRID_IMAGE_HEIGHT;
      row[`${side}Title`] = c?.title ?? '';
      row[`${side}Price`] = c?.price ?? '';
      row[`${side}PriceClass`] = c?.priceClass ?? 'price';
      row[`${side}Compare`] = c?.compare ?? '';
      row[`${side}CompareVisibility`] = c?.compareVisibility ?? 'collapsed';
      row[`${side}Visibility`] = c ? 'visible' : 'hidden';
    }
    rows.push(row);
  }
  return rows;
}
'''
open(p,'w').write(s)

def card(side, col):
    return f'''<StackLayout col="{col}" testID="{{{{ {side}TestID }}}}" tap="onCardTap" side="{side}" visibility="{{{{ {side}Visibility }}}}">
  <Image src="{{{{ {side}Image }}}}" height="{{{{ {side}ImageHeight }}}}" stretch="aspectFill" class="img" loadMode="async" />
  <Label text="{{{{ {side}Title }}}}" class="card-title" maxLines="2" textWrap="true" />
  <StackLayout orientation="horizontal" marginTop="8">
    <Label text="{{{{ {side}Price }}}}" class="{{{{ {side}PriceClass }}}}" />
    <Label text="{{{{ {side}Compare }}}}" class="compare" visibility="{{{{ {side}CompareVisibility }}}}" verticalAlignment="bottom" marginBottom="1" />
  </StackLayout>
</StackLayout>'''
for p in ['pages/collection-page.xml','pages/home-page.xml']:
    s=open(p).read()
    m=re.search(r'( *)<StackLayout col="0" testID="\{\{ left\.testID \}\}".*?\n *</StackLayout>\n *<StackLayout col="2".*?\n( *)</StackLayout>\n', s, flags=re.S)
    ind=m.group(1)
    new='\n'.join(ind+l for l in (card('l',0)+'\n'+card('r',2)).split('\n'))+'\n'
    s=s[:m.start()]+new+s[m.end():]
    open(p,'w').write(s)
p='lib/card-tap.ts'
open(p,'w').write('''import type { EventData, View } from '@nativescript/core';
import { openProduct } from './nav';

/** Tap handler for a product card inside a 2-column grid row. */
export function onCardTap(args: EventData) {
  const view = args.object as View;
  const handle = view.bindingContext?.[`${view.get('side')}Handle`] as string;
  if (handle) openProduct(view, handle);
}
''')
EOF
